def valid_source(z):return z[0] in pos and bool(z[1]) and not set(z[2])&failtags and not re.search(r'^(?:Như\s|Xem\s|Biến thể|Alternative form|Alternative spelling)',z[1],re.I)
def hasparts(w,bag):
 x=w.split()
 return any(' '.join(t) in bag for i in range(len(x)) for t in (x[i:j] for j in range(i+1,min(i+4,len(x))+1)))
def old(w):return any(any(x in U.normalize('NFD',s) for x in tone) and re.search(r'(?:oa|oe|uy)$',no_tone(s)) and not re.fullmatch('quy',no_tone(s)) for s in w.split())
def issues(w,r):
 if not 4<=len(flat(w))<=16:return 'dài'
 if not all(re.fullmatch(r'(?:ngh|ng|nh|ch|gh|ph|th|tr|kh|gi|qu|[bcdđghklmnprstvx])?[aăâeêioôơuưy]{1,3}(?:ch|nh|ng|[cmnpt])?',no_tone(t)) and sum(c in tone for c in U.normalize('NFD',t))<=1 and (not re.search('(?:[cpt]|ch)$',t) or any(c in U.normalize('NFD',t) for c in ('\u0301','\u0323'))) for t in w.split()):return 'âm tiết'
 if old(w) or set(w.split())&variant or w in variant_words:return 'biến thể'
 vr=[z for z in r['v'] if valid_source(z)]; er=[z for z in r['e'] if valid_source(z)];
 if not vr and not (w in anchors and er and any(z[0] in pos and re.match(r'^Xem ',z[1]) for z in r['v'])):return 'từ điển'
 if flat(w) in keybad or w in badwords or hasparts(w,parts):return 'từ nhạy cảm'
 allz=[z for z in r['e']+r['v'] if z[0] in pos];
 if any(set(z[2])&hardtags or set(z[3])&bad_topics for z in allz) or any(vi_bad.search(z[1].lower()) for z in vr) or any(en_bad.search(z[1].lower()) for z in er):return 'nghĩa nhạy cảm'
 if not (F.get(w,0) or T.get(w,0) or w in anchors):return 'chứng liệu'
 return ''
def alternatives(w):
 out=set(); syll=w.split()
 for i,s in enumerate(syll):
  vv=set();n=U.normalize('NFD',s)
  for a,b in [('s','x'),('ch','tr'),('l','n'),('r','d'),('r','gi'),('d','gi')]:
   if s.startswith(a) and not (a=='n' and s.startswith(('ng','nh'))):vv.add(b+s[len(a):]);
   if s.startswith(b) and not (b=='n' and s.startswith(('ng','nh'))):vv.add(a+s[len(b):]);
  for a,b in [('c','t'),('n','ng')]:
   if s.endswith(a):vv.add(s[:-len(a)]+b)
   if s.endswith(b):vv.add(s[:-len(b)]+a)
  for a,b in [('\u0309','\u0303'),('\u0303','\u0309')]:
   if a in n:vv.add(nfc(n.replace(a,b)))
  for v in vv:out.add(' '.join(syll[:i]+[v]+syll[i+1:]))
 return out

def rank():
 reasons=collections.Counter();detail={}
 for w,r in D.items():
  f=issues(w,r)
  if f:reasons[f]+=1;continue
  v=[z for z in r['v'] if valid_source(z)]; e=[z for z in r['e'] if valid_source(z)]; L=len(w.split());phys=int(any(z[0]=='noun' and concrete_pat.search(z[1].lower()) for z in v));n=int(any(z[0]=='noun' for z in v));d1=F.get(w,0);d2=T.get(w,0);near=sorted(a for a in alternatives(w) if a in D and F.get(a,0)>=3 and any(valid_source(z) for z in D[a]['v']));asks=any(c in U.normalize('NFD',w) for c in ('\u0309','\u0303')); a=int(w in anchors); ex=int(bool(e));
  score=1.00*math.log2(1+d1)+1.55*math.log2(1+min(d2,50))+1.9*ex+2.6*phys+0.4*n+3.0*a-1.0*(L==1)-0.25*max(0,L-2)-0.18*max(0,len(flat(w))-10)-0.65*bool(near)-0.32*asks
